class M(type):
 def mro(cls):
  print(cls.__name__,cls.__mro__ is None)
  return type.mro(cls)
class C(metaclass=M): pass
print(C.__mro__==(C,object))

class A:
 def f(self): return 7
class B:
 def f(self): return 9
class M(type):
 def mro(cls): return [cls,B,A,object]
class C(A,B,metaclass=M):
 def f(self): return super().f()
print(C().f(),super(B,C()).f())

