class D:
 def __get__(self,obj,owner):
  print(obj.__name__,owner.__name__)
  return lambda:(obj,object)
class M(type): mro=D()
class C(metaclass=M): pass
print(C.__mro__==(C,object))

class M(type):
 def mro(cls):
  yield cls
  yield object
class C(metaclass=M): pass
print(C.__mro__==(C,object))

class Items:
 def __init__(self,cls): self.cls=cls
 def __iter__(self): print("iter"); return iter((self.cls,object))
 def __len__(self): print("len"); return 2
class M(type):
 def mro(cls): return Items(cls)
class C(metaclass=M): pass
print(C.__mro__==(C,object))

